const FPS = 60;
const CNT = 25;
const CLRS_H = ["purple", "darkred"];
const CLRS_V = ["darkgreen", "navy"];

const THF = 0.8; 
let S, TH;
let stripes;
let s_i = 0, sx_i = 0, sy_i = 0, s_h = true;

function setup() {
	createCanvas(S=max(windowWidth, windowHeight), S);
	describe("stripes forming a flocking by time")
	frameRate(FPS);

	S /= (CNT + 1);
	TH = S * THF;
	s_i = 0; sx_i = 0; sy_i = 0; s_h = true;
	stripes = [];
	// addStripe();

	background("beige");
	strokeWeight(TH);
}

function draw() {
	if (s_i > 8 * CNT) setup();
	addStripe();

	for (let s of stripes) {
		s.move();
	}
	for (let s of stripes) {
		s.show();
	}
}

function addStripe() {
	if (s_i > 2 * CNT + 1) {
		s_i++;
		return;
	}

	s_h = s_i % 2 === 0; // is horizontal, altering every step

	let clr, x, y, xd, yd;
	if (s_h) {
		clr = lerpColor(color(CLRS_H[0]), color(CLRS_H[1]), random());
		x = 0;
		y = S/2 + S * sy_i;
		sy_i++;
		xd = S;
		yd = 0;
	} else {
		clr = lerpColor(color(CLRS_V[0]), color(CLRS_V[1]), random());
		x = S/2 + S * sx_i;
		y = 0;
		sx_i++;
		xd = 0;
		yd = S;
	}
	stripes.push(new Stripe(x, y, xd/2, yd/2, S * 0.1, clr, s_i, (sx_i + sy_i) % 2 === 0))

	s_i++;
}


class Stripe {
	constructor(x, y, xd, yd, ds, clr, idx, mve) {
		this.idx = idx;
		this.x = x; // start position
		this.y = y;
		this.lx = x; // last position
		this.ly = y;
		this.xd = xd; // delta per step
		this.yd = yd;
		this.ds = ds; // adding randomness per step
		this.clr = clr; // color of stripe
		this.mve = mve;
	}

	move() {
		this.mve = !this.mve;
		if (this.mve) return;

		this.lx = this.x;
		this.ly = this.y;
		for (let i = 0; i < 2; i++) {			
			this.x += this.xd;
			this.y += this.yd;

			const ds = random(-this.ds, this.ds)
			if (this.xd === 0) {
				this.x += ds;
			} else {
				this.y += ds;			
			}
		}
	}

	show() {
		if (this.mve) return;
		stroke(this.clr);
		line(this.lx, this.ly, this.x, this.y)
		// if (this.idx === 0) console.log(`${this.lx}, ${this.ly}, ${this.x}, ${this.y}`)
	}
}
